    var (
        wg      sync.WaitGroup
        results []string
    )
    for _, u := range urls {
        go func() {
            wg.Add(1)
            defer wg.Done()
            body, _ := fetch(u)
            results = append(results, body)
        }()
    }
    wg.Wait()
    return results
